//! Old number lines, frozen: saved figures and their share links made before batch 7 (at 47e760a, the figure's
//! eighteen old controls), each with the hash of the SVG it drew then. A saved figure stores every param; a share link
//! lists only those that differ from the opening state. Both must still draw byte for byte what they drew.
//!
//! The fixture was written by the old code with `VERSHION_NL_FREEZE=1 cargo test --profile figtest --lib number_line_frozen`
//! and must never be regenerated by the new code. The few old figures that change on purpose are listed in `intended`.
use crate::figures::spec::{params_from_spec, value_to_json};
use crate::figures::{registry, start_params, FigureDef, Params, Value};

fn def() -> FigureDef { registry().into_iter().find(|d| d.id == "number-line").unwrap() }

fn fnv64(s: &str) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in s.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

fn fixture() -> std::path::PathBuf { std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/number_line_frozen.txt") }

/// Graph rows a teacher could have typed before batch 7 (inequalities, equations, words, junk, and the
/// sequence and point forms the old row could not draw).
pub(super) const OLD_ROWS: [&str; 44] = [
    "", "-2 < x <= 5", "x > 3", "x >= -2", "x < -1 or x >= 3", "x = 2", "x != 2", "x \u{2260} 2", "all real numbers", "no solution",
    "-3 < x \u{2264} 4", "x \u{2265} \u{2212}2", "2 >= x", "-1 <= x < 1", "x < -4 or x >= 1", "x > 0.5", "x <= 3/4", "x > pi/2", "x < -2pi",
    "x > 7", "x = -2.5", "-2.5 < x <= 5.3", "x>1 and x<4", "x < 2 \u{222a} x > 5", "X > 3", "x > 3 or", "x >", "hello", "3, -4, 5", "P(3/4)",
    "a_n = 1/n", "a\u{2099} = 1/n", "x_n = n^2", "y > 2", "x > 1000", "x < -1000", "-20 < x < 20", "x = 0", "0 < x < 0.1", "x >= 1/3",
    "x > 1e3", "1 < x < 1", "x > 2 or x > 5", "5 > x > 2",
];
/// Point lists a teacher could have typed.
pub(super) const OLD_POINTS: [&str; 22] = [
    "", "3, -4, 5", "P(3/4), Q(3/2), R(7/4)", "-8, 6o", "2.5, -4", "1, 1/2, 1/3, 1/4, 1/5, 1/6", "A(0.35), B(-2)", "pi/2, pi", "0o, 1o, 2", "1 1/4, -2 1/2",
    "P(1), Q(1.05), R(1.1)", "100, -100", "x", "3o, 3", "Alpha(2)", "2.25, 2.5, 2.75", "\u{2212}1, 2.5", "P(0.35)", "5o", ",, 3", "1/0", "2, 2.001",
];
const STEP_TEXT: [&str; 10] = ["", "1/4", "1/3", "1/2", "0.5", "pi/2", "pi", "2pi", "1/8", "3/4"];

/// The old controls' values, sampled: the examples, every row and point form, the ends of every range.
fn old_specs() -> Vec<Vec<(&'static str, Value)>> {
    let s = |t: &str| Value::S(t.into());
    let mut out: Vec<Vec<(&'static str, Value)>> = vec![vec![]];
    for r in OLD_ROWS { out.push(vec![("inequality", s(r))]); }
    for r in OLD_ROWS { out.push(vec![("inequality", s("x > 3")), ("inequality2", s(r))]); }
    for pts in OLD_POINTS { out.push(vec![("inequality", s("")), ("points", s(pts))]); }
    for pts in OLD_POINTS { out.push(vec![("inequality", s("")), ("points", s(pts)), ("pt_values", Value::B(true)), ("min", Value::F(0.0)), ("max", Value::F(2.0)), ("step_text", s("1/4"))]); }
    for st in STEP_TEXT { out.push(vec![("min", Value::F(-2.0)), ("max", Value::F(4.0)), ("step_text", s(st)), ("points", s("P(3/4), 1.5")), ("pt_values", Value::B(true))]); }
    for st in STEP_TEXT { out.push(vec![("min", Value::F(0.0)), ("max", Value::F(7.0)), ("step_text", s(st)), ("frac_style", s("Mixed (1 1/4)")), ("inequality", s("x > 1/2"))]); }
    // the examples
    out.push(vec![("inequality", s("x >= -2"))]);
    out.push(vec![("min", Value::F(0.0)), ("max", Value::F(2.0)), ("step_text", s("1/4")), ("label_every", Value::I(4)), ("inequality", s("")), ("points", s("P(3/4), Q(3/2), R(7/4)"))]);
    out.push(vec![("min", Value::F(0.0)), ("max", Value::F(1.0)), ("step", Value::F(0.1)), ("inequality", s("")), ("points", s("1, 1/2, 1/3, 1/4, 1/5, 1/6"))]);
    // ends of the ranges
    for (mn, mx, st) in [(-1000.0, 1000.0, 100.0), (-1000.0, 1000.0, 50.0), (0.0, 1.0, 0.05), (-10.0, -10.0, 1.0), (5.0, -5.0, 1.0), (0.0, 100.0, 0.5), (-3.0, 3.0, 0.25)] {
        for ls in ["Large", "Medium", "Small"] {
            out.push(vec![("min", Value::F(mn)), ("max", Value::F(mx)), ("step", Value::F(st)), ("label_size", s(ls)), ("inequality", s("-2 < x <= 5")), ("points", s("P(1), 3o"))]);
        }
    }
    // a seeded mix of everything
    let mut seed: u64 = 0x5eed_0b17_4e17;
    let mut next = |n: u64| { seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407); (seed >> 33) % n };
    let colors = ["#111111", "#1f5fbf", "#c0392b", "#2a8a3e", "#8e44ad", "#d68910"];
    while out.len() < 320 {
        let mn = -20.0 + next(21) as f64;
        out.push(vec![
            ("min", Value::F(mn)), ("max", Value::F(mn + 1.0 + next(30) as f64)), ("step", Value::F([0.25, 0.5, 1.0, 2.0, 5.0][next(5) as usize])),
            ("label_every", Value::I(1 + next(5) as i64)), ("minor", Value::I(next(5) as i64)), ("numbers", Value::B(next(5) != 0)), ("arrows", Value::B(next(4) != 0)),
            ("inequality", s(OLD_ROWS[next(OLD_ROWS.len() as u64) as usize])), ("inequality2", s(if next(3) == 0 { OLD_ROWS[next(OLD_ROWS.len() as u64) as usize] } else { "" })),
            ("points", s(OLD_POINTS[next(OLD_POINTS.len() as u64) as usize])), ("label", s(["", "x", "Temperature (\u{b0}C)"][next(3) as usize])),
            ("ineq_color", s(colors[next(6) as usize])), ("pt_color", s(colors[next(6) as usize])), ("ineq2_color", s(colors[next(6) as usize])),
            ("step_text", s(if next(3) == 0 { STEP_TEXT[next(STEP_TEXT.len() as u64) as usize] } else { "" })),
            ("frac_style", s(["Improper (5/4)", "Mixed (1 1/4)"][next(2) as usize])), ("label_size", s(["Large", "Medium", "Small"][next(3) as usize])),
            ("pt_values", Value::B(next(2) == 0)),
        ]);
    }
    out
}

/// The params the old code built from a spec: its defaults overlaid with the spec.
fn old_params(d: &FigureDef, list: &[(&'static str, Value)]) -> Params {
    let mut p = start_params(d);
    for (k, v) in list { p.0.insert(k.to_string(), v.clone()); }
    p.normalize(&(d.params)(), false);
    p
}

/// Only the keys the old figure had (a saved figure from before stores exactly these).
pub(super) const OLD_KEYS: [&str; 18] = [
    "min", "max", "step", "label_every", "minor", "numbers", "arrows", "inequality", "points", "label", "ineq_color", "pt_color", "step_text", "frac_style",
    "inequality2", "label_size", "ineq2_color", "pt_values",
];

#[test]
fn number_line_frozen() {
    let d = def();
    if crate::env_var("VERSHION_NL_FREEZE").is_ok_and(|v| v == "1") {
        let start = start_params(&d);
        let mut text = String::new();
        for list in old_specs() {
            let p = old_params(&d, &list);
            let spec: serde_json::Map<String, serde_json::Value> = OLD_KEYS.iter().map(|k| (k.to_string(), value_to_json(p.0.get(*k).unwrap()))).collect();
            let link: serde_json::Map<String, serde_json::Value> = OLD_KEYS.iter().filter(|k| start.0.get(**k) != p.0.get(**k)).map(|k| (k.to_string(), value_to_json(p.0.get(*k).unwrap()))).collect();
            text.push_str(&format!("{:016x}\t{}\t{}\n", fnv64(&d.svg(&p)), serde_json::Value::Object(spec), serde_json::Value::Object(link)));
        }
        std::fs::write(fixture(), text).unwrap();
        return;
    }
    let text = std::fs::read_to_string(fixture()).unwrap();
    let (mut n, mut changed) = (0, 0);
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let mut it = line.split('\t');
        let (hash, spec, link) = (it.next().unwrap(), it.next().unwrap(), it.next().unwrap());
        let spec: serde_json::Map<String, serde_json::Value> = serde_json::from_str(spec).unwrap();
        let link: serde_json::Map<String, serde_json::Value> = serde_json::from_str(link).unwrap();
        let saved = params_from_spec(&d, &crate::model::FigureSpec { id: d.id.into(), params: spec.clone().into_iter().collect() });
        let shared: Vec<Params> = [crate::figures::share::VERSION, 1].iter().map(|v| crate::figures::share::link_params(&d, link.clone(), *v)).collect();
        if intended(&spec) {
            for p in std::iter::once(&saved).chain(&shared) {
                assert_ne!(format!("{:016x}", fnv64(&d.svg(p))), hash, "{spec:?}: meant to change but drawn as before");
            }
            changed += 1;
        } else {
            assert_eq!(format!("{:016x}", fnv64(&d.svg(&saved))), hash, "saved figure {spec:?} draws differently");
            for p in &shared {
                assert_eq!(format!("{:016x}", fnv64(&d.svg(p))), hash, "share link {link:?} draws differently");
            }
        }
        n += 1;
    }
    assert_eq!(n, 320);
    eprintln!("number line frozen: {n} old figures, {changed} changed on purpose");
}

/// The old figures that change on purpose (filled in with the change that makes them; see the module doc).
fn intended(_spec: &serde_json::Map<String, serde_json::Value>) -> bool { false }
